head.b:skin:
:root{
  --blue-50:#eff6ff;
  --blue-100:#dbeafe;
  --blue-200:#bfdbfe;
  --blue-500:#3b82f6;
  --blue-600:#2563eb;
  --blue-700:#1d4ed8;
  --blue-900:#1e3a8a;
  --ink:#0f172a;
  --ink-soft:#475569;
  --paper:#ffffff;
  --bg:#f4f7fc;
  --border:#e2e8f0;
  --radius:16px;
  --font-body:'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-serif:'Merriweather', Georgia, serif;
  --max-w:720px;
}
@media (prefers-color-scheme: dark){
  :root{
    --ink:#e2e8f0;
    --ink-soft:#94a3b8;
    --paper:#111827;
    --bg:#0b1120;
    --border:#1f2937;
    --blue-50:#0f1b33;
    --blue-100:#122246;
  }
}
*{box-sizing:border-box;}
html{scroll-behavior:smooth;}
body{
  margin:0;
  background:var(--bg);
  color:var(--ink);
  font-family:var(--font-body);
  line-height:1.65;
  -webkit-font-smoothing:antialiased;
}
a{color:var(--blue-600); text-decoration:none;}
a:hover{color:var(--blue-700); text-decoration:underline;}
img{max-width:100%; height:auto; display:block;}

/* Header */
.site-header{
  background:linear-gradient(135deg, var(--blue-700), var(--blue-500));
  color:#fff;
  padding:56px 24px 64px;
  text-align:center;
}
.site-title{
  margin:0;
  font-size:clamp(28px,5vw,42px);
  font-weight:800;
  letter-spacing:-0.02em;
}
.site-title a{color:#fff; text-decoration:none;}
.site-description{
  margin:10px auto 0;
  max-width:520px;
  color:var(--blue-100);
  font-size:16px;
  font-weight:500;
}

/* Layout */
.content-wrap{
  max-width:var(--max-w);
  margin:-32px auto 0;
  padding:0 20px 60px;
}
.blog-posts{
  display:flex;
  flex-direction:column;
  gap:28px;
}

/* Post card */
.post-card{
  background:var(--paper);
  border:1px solid var(--border);
  border-radius:var(--radius);
  padding:32px clamp(20px,5vw,44px);
  box-shadow:0 1px 2px rgba(15,23,42,0.04), 0 12px 32px -16px rgba(30,58,138,0.18);
  margin-bottom:28px;
}
.post-title{
  font-size:clamp(22px,4vw,32px);
  font-weight:800;
  line-height:1.25;
  letter-spacing:-0.01em;
  margin:0 0 12px;
}
.post-title a{color:var(--ink);}
.post-title a:hover{color:var(--blue-600); text-decoration:none;}
.post-meta{
  display:flex;
  flex-wrap:wrap;
  gap:10px 16px;
  font-size:13px;
  font-weight:600;
  color:var(--ink-soft);
  text-transform:uppercase;
  letter-spacing:0.04em;
  margin-bottom:22px;
}
.post-meta .post-date{color:var(--blue-600);}

.post-body{
  font-family:var(--font-serif);
  font-size:18px;
  color:var(--ink);
}
.post-body p{margin:0 0 20px;}
.post-body h1,.post-body h2,.post-body h3,.post-body h4{
  font-family:var(--font-body);
  font-weight:700;
  color:var(--ink);
  margin:32px 0 14px;
}
.post-body blockquote{
  margin:24px 0;
  padding:4px 20px;
  border-left:4px solid var(--blue-500);
  background:var(--blue-50);
  color:var(--ink-soft);
  font-style:italic;
  border-radius:0 8px 8px 0;
}
.post-body pre, .post-body code{
  font-family:'SFMono-Regular', Consolas, monospace;
  background:var(--blue-50);
  border-radius:6px;
}
.post-body pre{padding:16px; overflow-x:auto;}
.post-body code{padding:2px 6px; font-size:0.9em;}
.post-body img, .post-body iframe{border-radius:12px; margin:20px 0;}
.post-body a{text-decoration:underline; text-decoration-color:var(--blue-200);}

/* Tables (e.g. tokenomics) */
.post-body table{
  width:100%;
  border-collapse:collapse;
  margin:24px 0;
  font-family:var(--font-body);
  font-size:15px;
}
.post-body th, .post-body td{
  padding:12px 14px;
  border:1px solid var(--border);
  text-align:left;
}
.post-body th{
  background:var(--blue-50);
  color:var(--blue-900);
  font-weight:700;
}
.post-body tr:nth-child(even) td{background:rgba(37,99,235,0.03);}

/* Stat cards (e.g. token details grid) */
.stat-grid{
  display:grid;
  grid-template-columns:repeat(auto-fit, minmax(140px,1fr));
  gap:12px;
  margin:24px 0;
}
.stat-card{
  background:var(--blue-50);
  border:1px solid var(--border);
  border-radius:12px;
  padding:16px;
  text-align:center;
}
.stat-card .stat-label{
  display:block;
  font-size:12px;
  font-weight:700;
  text-transform:uppercase;
  letter-spacing:0.04em;
  color:var(--ink-soft);
  margin-bottom:6px;
}
.stat-card .stat-value{
  display:block;
  font-family:var(--font-body);
  font-size:18px;
  font-weight:800;
  color:var(--blue-700);
}

/* Callout boxes */
.callout{
  margin:24px 0;
  padding:16px 20px;
  border-radius:12px;
  border:1px solid var(--border);
  background:var(--blue-50);
  font-family:var(--font-body);
  font-size:15px;
}
.callout-warning{
  background:#fff7ed;
  border-color:#fdba74;
  color:#7c2d12;
}
.callout-warning strong{color:#9a3412;}
.callout strong{color:var(--blue-900);}

/* CTA button (e.g. how to buy) */
.btn{
  display:inline-block;
  background:var(--blue-600);
  color:#fff !important;
  font-family:var(--font-body);
  font-weight:700;
  padding:12px 24px;
  border-radius:10px;
  text-decoration:none !important;
  margin:6px 8px 6px 0;
}
.btn:hover{background:var(--blue-700);}
.btn-outline{
  background:transparent;
  color:var(--blue-600) !important;
  border:2px solid var(--blue-500);
  padding:10px 22px;
}
.btn-outline:hover{background:var(--blue-50);}

.read-more{margin-top:8px;}
.read-more a{
  display:inline-block;
  font-weight:700;
  color:var(--blue-600);
}

.post-footer{
  margin-top:28px;
  padding-top:20px;
  border-top:1px solid var(--border);
  display:flex;
  flex-wrap:wrap;
  align-items:center;
  justify-content:space-between;
  gap:12px;
}
.post-labels{display:flex; flex-wrap:wrap; gap:8px;}
.post-labels a{
  background:var(--blue-50);
  color:var(--blue-700);
  font-size:12px;
  font-weight:700;
  padding:5px 12px;
  border-radius:999px;
}
.post-labels a:hover{background:var(--blue-100); text-decoration:none;}
.comment-link{font-size:13px; font-weight:700; color:var(--ink-soft);}

/* Comments (Blogger default markup, restyled) */
.comments{margin-top:32px; padding-top:24px; border-top:1px solid var(--border);}
.comments h4{font-size:18px; font-weight:800; margin:0 0 16px;}
#comments-block{margin:0;}
.comment-author{font-weight:700; font-size:14px; margin-top:16px;}
.comment-body{margin:4px 0 0; color:var(--ink-soft); font-size:15px;}
.comment-footer{margin-top:18px;}

/* Pager */
.blog-pager{
  display:flex;
  justify-content:space-between;
  gap:12px;
  margin-top:8px;
}
.blog-pager a{
  flex:1;
  text-align:center;
  padding:14px 18px;
  background:var(--paper);
  border:1px solid var(--border);
  border-radius:12px;
  font-weight:700;
  color:var(--ink);
}
.blog-pager a:hover{
  border-color:var(--blue-500);
  color:var(--blue-600);
  text-decoration:none;
}

/* Footer */
.site-footer{
  text-align:center;
  padding:32px 20px 48px;
  color:var(--ink-soft);
  font-size:13px;
}
.site-footer a{color:var(--ink-soft); font-weight:600;}

/* Status message (no posts, search results empty, etc.) */
.status-msg-wrap{
  background:var(--paper);
  border:1px solid var(--border);
  border-radius:var(--radius);
  padding:24px;
  text-align:center;
  color:var(--ink-soft);
}

@media (max-width:640px){
  .site-header{padding:40px 20px 52px;}
  .content-wrap{margin-top:-24px;}
  .post-card{padding:26px 20px;}
}
